Sau khi thêm hàm này, bạn chỉ cần gọi GoogleLoginButtonGiangVien(...) trong màn hình đăng nhập giảng viên (tương tự như cách gọi GoogleLoginButtonSinhVien cho sinh viên).

Mình sẽ tiến hành thêm hàm này ngay bên dưới GoogleLoginButtonSinhVien."}],"tool_calls":[{"id":"call_KgBCs7mrg3WhHb0GtQPu9EkX","type":"function","function":{"name":"edit_file","arguments":"{"target_file":"app/src/main/java/com/example/ckcitlabroom/views/SinhVien/LoginSVScreen.kt","instructions":"Thêm một composable mới tên GoogleLoginButtonGiangVien vào cuối file này, chức năng tương tự như GoogleLoginButtonSinhVien nhưng dành cho giảng viên, sử dụng GiangVienViewModel, GiangVienPreferences và lấy thông tin giảng viên, lưu token, điều hướng về HOME khi đăng nhập thành công.","code_edit":"\n// Đăng nhập Google dành cho giảng viên\n@Composable\nfun GoogleLoginButtonGiangVien(\n giangVienViewModel: GiangVienViewModel,\n navController: NavHostController\n) {\n val context = LocalContext.current\n val activity = context as Activity\n val auth = FirebaseAuth.getInstance()\n val lifecycleScope = (LocalContext.current as ComponentActivity).lifecycleScope\n\n val userPreferences = remember { GiangVienPreferences(context) }\n val isLoading = remember { mutableStateOf(false) }\n\n val gso = GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)\n .requestIdToken(\"833001661760-qrmhtiovh0s953a12n6u8hqmni8j7k52.apps.googleusercontent.com\")\n .requestEmail()\n .build()\n\n val googleSignInClient = GoogleSignIn.getClient(context, gso)\n\n val launcher = rememberLauncherForActivityResult(\n contract = ActivityResultContracts.StartActivityForResult()\n ) { result ->\n val task = GoogleSignIn.getSignedInAccountFromIntent(result.data)\n try {\n val account = task.getResult(ApiException::class.java)\n Log.d(\"GoogleSignInGV\", \"Tài khoản Google: ${account.email}\")\n isLoading.value = true\n\n lifecycleScope.launch {\n try {\n val credential = GoogleAuthProvider.getCredential(account.idToken, null)\n val authResult = auth.signInWithCredential(credential).await()\n\n val user = auth.currentUser\n val email = user?.email\n\n if (email != null && email.endsWith(\"@caothang.edu.vn\")) {\n // Lấy thông tin giảng viên\n val giangvien = withContext(Dispatchers.IO) {\n giangVienViewModel.getGiangVienByEmailNow(email)\n }\n\n if (giangvien != null) {\n Log.d(\"GiangVienLogin\", \"Giảng viên: $giangvien\")\n\n val token = FirebaseMessaging.getInstance().token.await()\n val giangvienWithToken = giangvien.copy(Token = token)\n\n giangVienViewModel.setToken(token)\n giangVienViewModel.updateToken(giangvien.MaGiangVien, token)\n\n userPreferences.saveLoginForGiangVien(giangvienWithToken)\n giangVienViewModel.setGV(giangvienWithToken)\n\n isLoading.value = false\n delay(300)\n\n navController.navigate(NavRoute.HOME.route) {\n popUpTo(0) { inclusive = true }\n }\n } else {\n isLoading.value = false\n Log.e(\"GiangVienLogin\", \"Không tìm thấy giảng viên với email $email\")\n Toast.makeText(\n context,\n \"Không tìm thấy thông tin giảng viên\",\n Toast.LENGTH_SHORT\n ).show()\n auth.signOut()\n }\n } else {\n isLoading.value = false\n auth.signOut()\n Toast.makeText(\n context,\n \"Vui lòng đăng nhập bằng email của trường\",\n Toast.LENGTH_SHORT\n ).show()\n googleSignInClient.signOut()\n }\n } catch (e: Exception) {\n isLoading.value = false\n Log.e(\"GoogleSignInGV\", \"Lỗi đăng nhập: $e\")\n Toast.makeText(context, \"Đăng nhập thất bại\", Toast.LENGTH_SHORT).show()\n }\n }\n } catch (e: Exception) {\n isLoading.value = false\n Log.e(\"GoogleSignInGV\", \"Lỗi lấy tài khoản Google: $e\")\n Toast.makeText(context, \"Đăng nhập Google thất bại\", Toast.LENGTH_SHORT).show()\n }\n }\n\n Button(\n onClick = {\n isLoading.value = true\n googleSignInClient.signOut().addOnCompleteListener {\n launcher.launch(googleSignInClient.signInIntent)\n }\n },\n modifier = Modifier\n .padding(horizontal = 24.dp, vertical = 12.dp)\n .height(50.dp)\n .shadow(6.dp, RoundedCornerShape(12.dp)),\n colors = ButtonDefaults.buttonColors(\n containerColor = Color.White,\n contentColor = Color.Black\n ),\n shape = RoundedCornerShape(12.dp)\n ) {\n Row(\n verticalAlignment = Alignm