 composable(
 route = NavRoute.QUETQRCODE.route,
 enterTransition = defaultEnterTransition(AnimatedContentTransitionScope.SlideDirection.Start),
 exitTransition = defaultExitTransition(AnimatedContentTransitionScope.SlideDirection.End)
 ) {
 val context = LocalContext.current
 val danhSachMay by mayTinhViewModel.danhSachAllMayTinh2.collectAsState(emptyList())
 var isDataLoaded by remember { mutableStateOf(false) }

 LaunchedEffect(Unit) {
 if (!isDataLoaded) {
 mayTinhViewModel.getAllMayTinh2()
 isDataLoaded = true
 }
 }

 when {
 danhSachMay.isEmpty() && !isDataLoaded -> {
 Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
 DotLoading()
 }
 }

 danhSachMay.isEmpty() && isDataLoaded -> {
 Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
 Text("Không có dữ liệu máy tính hoặc lỗi tải.")
 }
 }

 else -> {
 QRCodeScannerScreen { qrCodeValue ->
 val tonTai = danhSachMay.any { it.MaMay == qrCodeValue }

 var maytinh = mayTinhViewModel.maytinh




 caHocViewModel.getAllCaHoc()
 mayTinhViewModel.getMayTinhByMaMay(qrCodeValue)


 val danhSachCaHoc = caHocViewModel.danhSachAllCaHoc
 val danhSachLichHoc = lichHocViewModel.danhSachLichHoc

 // Lấy giờ hiện tại
 val formatter = DateTimeFormatter.ofPattern("HH:mm:ss")
 val gioHienTai = LocalTime.now().format(formatter)

 // Tìm ca học hiện tại
 val caHienTai = danhSachCaHoc.firstOrNull {
 it.GioBatDau <= gioHienTai && it.GioKetThuc >= gioHienTai
 }

 // Lấy danh sách lịch học khớp với ca hiện tại
 val danhSachLichHocHienTai by remember(caHienTai, danhSachLichHoc) {
 if (caHienTai != null) {
 val ngayHomNay = LocalDate.now().toString() // yyyy-MM-dd
 danhSachLichHoc
 .filter {
 it.MaCaHoc == caHienTai.MaCaHoc && it.NgayDay == ngayHomNay
 }
 .sortedBy { it.MaPhong } // sắp xếp theo MaPhong tăng dần
 } else emptyList()
 }

 var lichhochientai =
 danhSachLichHocHienTai.filter { it.vaMaPhong == maytinh.MaPhong }
 .firstOrNull()

 if (tonTai) {
 navController.navigate(NavRoute.MAYTINHDETAIL.route + "?mamay=$qrCodeValue&malichhoc=${lichhochientai!!.MaLichHoc}")
 } else {
 Toast.makeText(context, "Mã QR không hợp lệ", Toast.LENGTH_SHORT).show()
 }
 }
 }
 }
 }


