 fontWeight = FontWeight.Bold,
 fontSize = 17.sp
 )
 }
 }
 } else {
 items(danhsachdonnhap) { donnhap ->
 CardDonNhapChuyen(
 selectedPhong!!.MaPhong,
 donnhap,
 chiTietDonNhapViewModel,
 mayTinhViewModel,
 navController,
 click = {
