import android.content.Context
import android.net.Uri
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.apache.poi.ss.usermodel.WorkbookFactory
import java.io.InputStream

suspend fun parseExcelFileAndImport(
 context: Context,
 fileUri: Uri,
 giangVienViewModel: GiangVienViewModel
) {
 try {
 val inputStream: InputStream? = context.contentResolver.openInputStream(fileUri)
 if (inputStream != null) {
 val workbook = WorkbookFactory.create(inputStream)
 val sheet = workbook.getSheetAt(0)
 for (rowIndex in 1..sheet.lastRowNum) { // row 0 = header
 val row = sheet.getRow(rowIndex)
 if (row != null) {
 val maGV = row.getCell(0)?.toString()?.trim() ?: continue
 val tenGV = row.getCell(1)?.toString()?.trim() ?: continue
 val ngaySinh = row.getCell(2)?.toString()?.trim() ?: continue
 val gioiTinh = row.getCell(3)?.toString()?.trim() ?: continue
 val email = row.getCell(4)?.toString()?.trim() ?: continue

 // Kiểm tra trùng mã GV hoặc email
 val gvByMa = withContext(Dispatchers.IO) {
 giangVienViewModel.getGiangVienByMaGOrEmailNow(maGV)
 }
 val gvByEmail = withContext(Dispatchers.IO) {
 giangVienViewModel.getGiangVienByMaGOrEmailNow(email)
 }
 if (gvByMa != null || gvByEmail != null) {
 android.widget.Toast.makeText(
 context,
 "Giảng viên trùng mã hoặc email: $maGV, $email. Bỏ qua!",
 android.widget.Toast.LENGTH_SHORT
 ).show()
 continue
 }
 val giangVien = GiangVien(
 MaGV = maGV,
 TenGiangVien = tenGV,
 NgaySinh = ngaySinh,
 GioiTinh = gioiTinh,
 Email = email,
 MatKhau = hashPasswordMD5(maGV),
 MaLoaiTaiKhoan = 2,
 TrangThai = 1
 )
 giangVienViewModel.createGiangVien(giangVien)
 }
 }
 inputStream.close()
 android.widget.Toast.makeText(
 context,
 "Đã thêm danh sách giảng viên!",
 android.widget.Toast.LENGTH_LONG
 ).show()
 }
 } catch (e: Exception) {
 android.widget.Toast.makeText(
 context,
 "Lỗi khi đọc file Excel!",
 android.widget.Toast.LENGTH_LONG
 ).show()
 e.printStackTrace()
 }
}

```
