 Toast.LENGTH_SHORT
 ).show()
 continue
 }
 val giangVien = GiangVien(
 MaGV = maGV,
 TenGiangVien = tenGV,
 NgaySinh = ngaySinh,
 GioiTinh = gioiTinh,
 Email = email,
 MatKhau = hashPasswordMD5(maGV),
 MaLoaiTaiKhoan = 2,
 TrangThai = 1
 )
 giangVienViewModel.createGiangVien(giangVien)
 }
 }
 inputStream.close()
 android.widget.Toast.makeText(
