 .setTitle("Thông báo trùng")
 .setMessage(message)
 .setCancelable(false)
 .setPositiveButton("Xác nhận") { dialog, _ ->
 dialog.dismiss()
 continuation.resume(Unit)
 }
 .show()
 }
