 val danhSachAllGV = giangVienViewModel.danhSachAllGiangVien

 val inputStream: InputStream? = activity.contentResolver.openInputStream(fileUri)
 if (inputStream != null) {
 val workbook = WorkbookFactory.create(inputStream)
 val sheet = workbook.getSheetAt(0)
 for (rowIndex in 1..sheet.lastRowNum) { // row 0 = header
 val row = sheet.getRow(rowIndex)
 if (row != null) {
 val maGV = row.getCell(0)?.toString()?.trim() ?: continue
 val tenGV = row.getCell(1)?.toString()?.trim() ?: continue
 val ngaySinh = row.getCell(2)?.toString()?.trim() ?: continue
 val gioiTinh = row.getCell(3)?.toString()?.trim() ?: continue
 val email = row.getCell(4)?.toString()?.trim() ?: continue

 val gvTrungMa = danhSachAllGV.firstOrNull { it.MaGV == maGV }
 val gvTrungEmail = danhSachAllGV.firstOrNull { it.Email == email }
 if (gvTrungMa != null || gvTrungEmail != null) {
 val msg = when {
 gvTrungMa != null && gvTrungEmail != null ->
 "Giảng viên $tenGV trùng mã với ${gvTrungMa.TenGiangVien} và trùng email với ${gvTrungEmail.TenGiangVien}!"

 gvTrungMa != null ->
 "Giảng viên $tenGV trùng mã với giảng viên ${gvTrungMa.TenGiangVien}!"

 else ->
 "Giảng viên $tenGV trùng email với giảng viên ${gvTrungEmail?.TenGiangVien}!"
 }
 showDuplicateDialog(activity, msg)
 continue
 }

 val giangVien = GiangVien(
 MaGV = maGV,
 TenGiangVien = tenGV,
 NgaySinh = ngaySinh,
 GioiTinh = gioiTinh,
 Email = email,
 MatKhau = hashPasswordMD5(maGV),
 MaLoaiTaiKhoan = 2,
 TrangThai = 1
 )
 giangVienViewModel.createGiangVien(giangVien)
