- Lấy danh sách giảng viên hiện tại duy nhất một lần (làm tại thời điểm gọi hàm).
- Kiểm tra trùng mã hoặc email so với danh sách này, nếu trùng thì hiện AlertDialog, chờ xác nhận rồi mới tiếp tục import.
- Tất cả thao tác và dialog đều dùng activity chuẩn.
- Chỉ thêm giảng viên mới khi không trùng, cuối cùng hiển thị toast thành công hoặc lỗi.

---

```kotlin
import android.net.Uri
import android.widget.Toast
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import kotlinx.coroutines.suspendCancellableCoroutine
import org.apache.poi.ss.usermodel.WorkbookFactory
import java.io.InputStream
import kotlin.coroutines.resume

private suspend fun showDuplicateDialog(activity: AppCompatActivity, message: String) {
 suspendCancellableCoroutine<Unit> { continuation ->
 AlertDialog.Builder(activity)
 .setTitle("Thông báo trùng")
 .setMessage(message)
 .setCancelable(false)
 .setPositiveButton("Xác nhận") { dialog, _ ->
 dialog.dismiss()
 continuation.resume(Unit)
 }
 .show()
 }
}

suspend fun parseExcelFileAndImport(
 activity: AppCompatActivity,
 fileUri: Uri,
 giangVienViewModel: GiangVienViewModel
) {
 try {
 // Lấy danh sách tất cả giảng viên hiện tại chỉ 1 lần duy nhất
 val danhSachAllGV = giangVienViewModel.danhSachAllGiangVien

 val inputStream: InputStream? = activity.contentResolver.openInputStream(fileUri)
 if (inputStream != null) {
 val workbook = WorkbookFactory.create(inputStream)
 val sheet = workbook.getSheetAt(0)
 for (rowIndex in 1..sheet.lastRowNum) { // row 0 = header
 val row = sheet.getRow(rowIndex)
 if (row != null) {
 val maGV = row.getCell(0)?.toString()?.trim() ?: continue
 val tenGV = row.getCell(1)?.toString()?.trim() ?: continue
 val ngaySinh = row.getCell(2)?.toString()?.trim() ?: continue
 val gioiTinh = row.getCell(3)?.toString()?.trim() ?: continue
 val email = row.getCell(4)?.toString()?.trim() ?: continue

 // Kiểm tra trùng
 val gvTrungMa = danhSachAllGV.firstOrNull { it.MaGV == maGV }
 val gvTrungEmail = danhSachAllGV.firstOrNull { it.Email == email }
 if (gvTrungMa != null || gvTrungEmail != null) {
 val msg = when {
 gvTrungMa != null && gvTrungEmail != null ->
 "Giảng viên '$tenGV' trùng mã với '${gvTrungMa.TenGiangVien}' và trùng email với '${gvTrungEmail.TenGiangVien}'!"
 gvTrungMa != null ->
 "Giảng viên '$tenGV' trùng mã với giảng viên '${gvTrungMa.TenGiangVien}'!"
 else ->
 "Giảng viên '$tenGV' trùng email với giảng viên '${gvTrungEmail?.TenGiangVien}'!"
 }
 // Hiện AlertDialog và chỉ tiếp tục khi người dùng xác nhận
 showDuplicateDialog(activity, msg)
 continue
 }

 val giangVien = GiangVien(
 MaGV = maGV,
 TenGiangVien = tenGV,
 NgaySinh = ngaySinh,
 GioiTinh = gioiTinh,
 Email = email,
 MatKhau = hashPasswordMD5(maGV),
 MaLoaiTaiKhoan = 2,
 TrangThai = 1
 )
 giangVienViewModel.createGiangVien(giangVien)
 }
 }
 inputStream.close()
 Toast.makeText(
 activity,
 "Đã thêm danh sách giảng viên!",
 Toast.LENGTH_LONG
 ).show()
 }
 } catch (e: Exception) {
 Toast.makeText(
 activity,
 "Lỗi khi đọc file Excel!",
 Toast.LENGTH_LONG
 ).show()
 e.printStackTrace()
 }
}
```

