 Toast.makeText(activity, "Sắp hiện dialog...", Toast.LENGTH_SHORT).show()
 showDuplicateDialog(activity, msg)
 continue
 }
 // ... code thêm mới
 }
 }
 inputStream.close()
 }
 } catch (e: Exception) {
 Toast.makeText(
 activity,
 "Lỗi: ${e.message}",
 Toast.LENGTH_LONG
 ).show()
 e.printStackTrace()
 }
}
