- Lấy toàn bộ danh sách giảng viên một lần (và đảm bảo lấy xong mới import!).
- Kiểm tra trùng trực tiếp trên list (không gọi lại API trong từng vòng for!).
- Nếu trùng, hiện AlertDialog xác nhận, phải bấm “Xác nhận” mới duyệt tiếp các giảng viên còn lại.
- Dùng context là AppCompatActivity cho AlertDialog.

**Lưu ý:** 
- Hàm này nên được gọi sau khi danhSachAllGiangVien đã được load đầy đủ từ ViewModel.
- Không nên đặt `giangVienViewModel.getAllGiangVien()` trong hàm này vì bất đồng bộ, truy xuất sẽ không có dữ liệu ngay.

---

```kotlin
import android.content.Context
import android.net.Uri
import android.widget.Toast
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import kotlinx.coroutines.suspendCancellableCoroutine
import org.apache.poi.ss.usermodel.WorkbookFactory
import java.io.InputStream
import kotlin.coroutines.resume

private suspend fun showDuplicateDialog(activity: AppCompatActivity, message: String) {
 suspendCancellableCoroutine<Unit> { continuation ->
 AlertDialog.Builder(activity)
 .setTitle("Thông báo trùng")
 .setMessage(message)
 .setCancelable(false)
 .setPositiveButton("Xác nhận") { dialog, _ ->
 dialog.dismiss()
 continuation.resume(Unit)
 }
 .show()
 }
}

suspend fun parseExcelFileAndImport(
 activity: AppCompatActivity, // YÊU CẦU truyền activity thật vào đây!
 fileUri: Uri,
 giangVienViewModel: GiangVienViewModel
) {
 // Không gọi getAllGiangVien() tại đây!
 val danhSachAllGV = giangVienViewModel.danhSachAllGiangVien

 try {
 val inputStream: InputStream? = activity.contentResolver.openInputStream(fileUri)
 if (inputStream != null) {
 val workbook = WorkbookFactory.create(inputStream)
 val sheet = workbook.getSheetAt(0)
 for (rowIndex in 1..sheet.lastRowNum) { // row 0 = header
 val row = sheet.getRow(rowIndex)
 if (row != null) {
 val maGV = row.getCell(0)?.toString()?.trim() ?: continue
 val tenGV = row.getCell(1)?.toString()?.trim() ?: continue
 val ngaySinh = row.getCell(2)?.toString()?.trim() ?: continue
 val gioiTinh = row.getCell(3)?.toString()?.trim() ?: continue
 val email = row.getCell(4)?.toString()?.trim() ?: continue

 // Kiểm tra trùng mã GV hoặc email trên list đã có!
 val gvTrungMa = danhSachAllGV.firstOrNull { it.MaGV == maGV }
 val gvTrungEmail = danhSachAllGV.firstOrNull { it.Email == email }
 if (gvTrungMa != null || gvTrungEmail != null) {
 val msg = when {
 gvTrungMa != null && gvTrungEmail != null ->
 "Giảng viên $tenGV trùng mã với ${gvTrungMa.TenGiangVien} và email với ${gvTrungEmail.TenGiangVien}!"
 gvTrungMa != null ->
 "Giảng viên $tenGV trùng mã với ${gvTrungMa.TenGiangVien}!"
 else ->
 "Giảng viên $tenGV trùng email với ${gvTrungEmail?.TenGiangVien}!"
 }
 showDuplicateDialog(activity, msg)
 continue
 }

 val giangVien = GiangVien(
 MaGV = maGV,
 TenGiangVien = tenGV,
 NgaySinh = ngaySinh,
 GioiTinh = gioiTinh,
 Email = email,
 MatKhau = hashPasswordMD5(maGV),
 MaLoaiTaiKhoan = 2,
 TrangThai = 1
 )
 giangVienViewModel.createGiangVien(giangVien)
 // Sau khi thêm, nếu muốn không cho cùng GV được import lại thì thêm vào danhSachAllGV nếu đây là list mutable
 }
 }
 inputStream.close()
 Toast.makeText(
 activity,
 "Đã thêm danh sách giảng viên!",
 Toast.LENGTH_LONG
 ).show()
 }
 } catch (e: Exception) {
 Toast.makeText(
 activity,
 "Lỗi khi đọc file Excel!",
 Toast.LENGTH_LONG
 ).show()
 e.printStackTrace()
 }
}
```

---

**Cách gọi trong Compose:**
- Đảm bảo truyền `activity = LocalContext.current as AppCompatActivity` (và chỉ truyền nếu ép kiểu không null).
- Chỉ chạy hàm import khi `giangVienViewModel.danhSachAllGiangVien.isNotEmpty()`.

---

Nếu bạn cần mình tích hợp luôn vào code Compose màn hình tạo giảng viên, hãy gửi đoạn đó mình sẽ viết ghép vào hoàn thiện nhất cho bạn nhé!"}]},{"role":"user","content":[{"type":"text","text":"
