- Lấy toàn bộ danh sách sinh viên từ ViewModel một lần duy nhất trước khi import.
- Khi duyệt từng dòng trong file Excel, kiểm tra trùng mã sinh viên hoặc email hoặc mã số bất kỳ dựa trên danh sách vừa lấy.
- Nếu trùng, hiện Toast báo rõ trùng mã sinh viên/email với ai để người dùng nhận biết, và tự động bỏ qua dòng đó.
- Nếu không trùng, tiếp tục thêm mới.

Dưới đây là ví dụ code thêm sinh viên dạng chuẩn như bạn cần (ví dụ student là SinhVien, SV là viết tắt của Sinh Viên):

---

```kotlin
import android.content.Context
import android.net.Uri
import android.widget.Toast
import org.apache.poi.ss.usermodel.WorkbookFactory
import java.io.InputStream

suspend fun parseExcelFileAndImportSinhVien(
 context: Context,
 fileUri: Uri,
 sinhVienViewModel: SinhVienViewModel
) {
 // Lấy danh sách sinh viên hiện tại một lần duy nhất
 val danhSachAllSV = sinhVienViewModel.danhSachAllSinhVien

 try {
 val inputStream: InputStream? = context.contentResolver.openInputStream(fileUri)
 if (inputStream != null) {
 val workbook = WorkbookFactory.create(inputStream)
 val sheet = workbook.getSheetAt(0)
 for (rowIndex in 1..sheet.lastRowNum) { // row 0 = header
 val row = sheet.getRow(rowIndex)
 if (row != null) {
 val maSV = row.getCell(0)?.toString()?.trim() ?: continue
 val tenSV = row.getCell(1)?.toString()?.trim() ?: continue
 val ngaySinh = row.getCell(2)?.toString()?.trim() ?: continue
 val gioiTinh = row.getCell(3)?.toString()?.trim() ?: continue
 val email = row.getCell(4)?.toString()?.trim() ?: continue

 // Kiểm tra trùng mã SV hoặc email bằng list đã lấy!
 val svByMa = danhSachAllSV.firstOrNull { it.MaSV == maSV }
 val svByEmail = danhSachAllSV.firstOrNull { it.Email == email }
 if (svByMa != null || svByEmail != null) {
 val message = when {
 svByMa != null && svByEmail != null ->
 "Sinh viên $tenSV bị trùng Mã SV với (${svByMa.TenSinhVien}) và trùng Email với (${svByEmail.TenSinhVien})! Bỏ qua."
 svByMa != null ->
 "Sinh viên $tenSV bị trùng Mã SV với (${svByMa.TenSinhVien})! Bỏ qua."
 svByEmail != null ->
 "Sinh viên $tenSV bị trùng Email với (${svByEmail.TenSinhVien})! Bỏ qua."
 else -> ""
 }
 Toast.makeText(context, message, Toast.LENGTH_SHORT).show()
 continue
 }
 val sinhVien = SinhVien(
 MaSV = maSV,
 TenSinhVien = tenSV,
 NgaySinh = ngaySinh,
 GioiTinh = gioiTinh,
 Email = email,
 // ... các trường khác tương ứng của entity SinhVien
 )
 sinhVienViewModel.createSinhVien(sinhVien)
 }
 }
 inputStream.close()
 Toast.makeText(
 context,
 "Đã thêm danh sách sinh viên!",
 Toast.LENGTH_LONG
 ).show()
 }
 } catch (e: Exception) {
 Toast.makeText(
 context,
 "Lỗi khi đọc file Excel!",
 Toast.LENGTH_LONG
 ).show()
 e.printStackTrace()
 }
}
```

