## **Ví dụ luồng xử lý (giả lập code Kotlin Jetpack Compose):**

```kotlin
// 1. Một màn hình đăng nhập
@Composable
fun LoginScreen(viewModel: LoginViewModel, onLoginSuccess: (Int) -> Unit) {
 var username by remember { mutableStateOf("") }
 var password by remember { mutableStateOf("") }
 // Có thể thêm dropdown nếu muốn

 // ... UI nhập username, password, nút đăng nhập ...
 Button(onClick = {
 // Gọi ViewModel/Repository login
 viewModel.login(username, password)
 }) { Text("Đăng nhập") }

 // Lắng nghe kết quả đăng nhập kèm role
 val loginResult by viewModel.loginResult.collectAsState()
 loginResult?.let { role ->
 onLoginSuccess(role.LoaiTaiKhoan)
 }
}
```

```kotlin
// 2. ViewModel gọi API login, trả về role
fun login(username: String, password: String) {
 viewModelScope.launch {
 // Call API, trả ra thông tin user kèm LoaiTaiKhoan
 val user = repository.login(username, password)
 if (user != null) {
 _loginResult.emit(user)
 }
 }
}
```

